-- DEMO50 rich student demo pack

delete from public.class_timetable where school_id = 'd5a00000-0000-4000-8000-000000000050'::uuid;


delete from public.attendance where school_id = 'd5a00000-0000-4000-8000-000000000050'::uuid;


delete from public.broadcasts where school_id = 'd5a00000-0000-4000-8000-000000000050'::uuid;

delete from public.calendar_events where school_id = 'd5a00000-0000-4000-8000-000000000050'::uuid;


select 'd5a00000-0000-4000-8000-000000000050'::uuid, v.class_name, v.subject, v.task, v.due_label, v.xp, v.difficulty, false
from (values
  ('Grade 8-A', 'Mathematics', 'DEMO50: Finish exercise set B (quadratic intro)', 'Friday', 50, 'Medium'),
  ('Grade 8-A', 'Science', 'DEMO50: Cell organelle flashcards — 10 terms', 'Tomorrow', 40, 'Easy'),
  ('Grade 8-A', 'English', 'DEMO50: Write a 150-word diary on school sports day', 'Wednesday', 35, 'Easy'),
  ('Grade 8-A', 'Social Studies', 'DEMO50: Map the Indian states — outline worksheet', 'Monday', 45, 'Medium'),
  ('Grade 8-A', 'Mathematics', 'DEMO50: Practice paper — 20 MCQs (Orbit GK Math warm-up)', 'Thursday', 55, 'Hard')
) as v(class_name, subject, task, due_label, xp, difficulty)
where not exists (
  select 1 from public.homework_tasks ht
  where ht.school_id = 'd5a00000-0000-4000-8000-000000000050'::uuid and ht.task = v.task
);

values ('d5a00000-0000-4000-8000-000000000050'::uuid, 'Grade 8-A', '[{"id":"ch_math_1","subject":"Mathematics","title":"Linear Equations","status":"completed","progress":100,"topics":["One-variable equations","Word problems"]},{"id":"ch_math_2","subject":"Mathematics","title":"Quadrilaterals","status":"in_progress","progress":55,"topics":["Properties","Constructions"]},{"id":"ch_sci_1","subject":"Science","title":"Cell Structure","status":"in_progress","progress":70,"topics":["Plant cell","Animal cell","Organelles"]},{"id":"ch_sci_2","subject":"Science","title":"Force and Pressure","status":"not_started","progress":0,"topics":["Pressure","Buoyancy"]},{"id":"ch_eng_1","subject":"English","title":"Grammar — Tenses","status":"completed","progress":100,"topics":["Present perfect","Past continuous"]},{"id":"ch_soc_1","subject":"Social Studies","title":"Indian Constitution basics","status":"in_progress","progress":40,"topics":["Preamble","Fundamental rights"]}]'::jsonb, now())
on conflict (school_id, class_name) do update
  set curriculum = excluded.curriculum, updated_at = now();

update public.profiles
set display_name = 'Manoj Mukherjee', subtitle = 'Grade 8-A · DEMO50', updated_at = now()
where email = 'student040@demo50.orbit.app';
update public.students
set profile_id = (select id from public.profiles where email = 'student040@demo50.orbit.app')
where id = 'd5000000-0000-4000-8000-000000000040'::uuid;
